import{z as B,x as o,o as A,c as d,q as l,j as r,D as e,d as i,s as n,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"单纯形","description":"","frontmatter":{"title":"单纯形","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/simplex.md","filePath":"cs/simplex.md","lastUpdated":1791413859000}'),p={name:"cs/simplex.md"};function m(D,a,C,h,F,_){const t=o("Mermaid");return A(),d("div",null,[a[2]||(a[2]=l('<h1 id="单纯形" tabindex="-1">单纯形 <a class="header-anchor" href="#单纯形" aria-label="Permalink to &quot;单纯形&quot;">​</a></h1><div class="epigraph"><p>线性规划的最优在顶点；单纯形沿基可行解走邻边，目标不减，直到检验数都非正。</p><footer>—— 据 Dantzig, Linear Programming and Extensions, 1963；CLRS 第 29 章整理</footer></div><p>上一课<a href="/cs/gaussian-elimination-xor-basis">高斯消元</a>解等式。线性规划（LP）：线性目标 + 线性不等式。缺口是单纯形：基、松弛变量、转轴。不重写消元的 \\(O(n^3)\\) 单次，转轴就是一次消元。后课对偶。Klee–Minty 最坏指数点名。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准形 \\(\\max c^\\top x\\)，\\(Ax=b\\)，\\(x\\ge 0\\)。基 \\(B\\)：\\(A_B\\) 可逆，\\(x_B=A_B^{-1}b\\ge 0\\)，非基为 0。目标用非基变量写，系数（检验数）全 \\(\\le 0\\) 则最优。否则选入基，比值检验选出基，转轴。有限顶点，若 degeneracy 须防循环（Bland）。</p><p>缺口是顶点游走，不是内点（后课）。多项式界不是单纯形最坏给出的——Khachiyan/Karmarkar 另路。</p><h3 id="不是整数规划" tabindex="-1">不是整数规划 <a class="header-anchor" href="#不是整数规划" aria-label="Permalink to &quot;不是整数规划&quot;">​</a></h3><p>顶点可以分数。整数约束后课分支定界。不要把单纯形当 ILP 求解器。</p><p><span class="marginnote">Dantzig 单纯形。CLRS 29。Klee–Minty 1972 指数实例。后课弱对偶、强对偶、互补松弛。</span></p><p><span class="marginnote">数字实例：比值检验就是在问「谁先撞墙」。设某列转轴时约束行给出 \\(x_B=(4,\\,6)\\)、系数 \\(a=(2,\\,3)\\)，则比值 \\(4/2=2\\)、\\(6/3=2\\)——最小的 \\(2\\) 就是能沿这条边走多远；哪个行给出最小比值，哪个基变量就出基。</span></p><p><span class="marginnote">初学者容易以为「最坏指数复杂度」意味着单纯形不实用。实际上它在工业 LP 求解器里数十年是主力：真实问题的多面体很少长成 Klee–Minty 那种故意构造的形状，单纯形往往几步转轴就到达顶点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>引入松弛变标准形。找初始基（两阶段或大 M）。循环转轴直到最优或无界（某列可无限增加）。</p>',13)),(A(),r(s,null,{default:e(()=>[n(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LP%5B%22LP%20%E6%A0%87%E5%87%86%E5%BD%A2%22%5D%20--%3E%20BFS%5B%22%E5%9F%BA%E5%8F%AF%E8%A1%8C%E8%A7%A3%22%5D%0A%20%20BFS%20--%3E%20RED%5B%22%E6%A3%80%E9%AA%8C%E6%95%B0%22%5D%0A%20%20RED%20--%3E%20PIV%5B%22%E8%BD%AC%E8%BD%B4%E9%82%BB%E9%A1%B6%E7%82%B9%22%5D%0A%20%20PIV%20--%3E%20BFS%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"实现用表或修正单纯形。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"可行域多面体，最优可达顶点（有界时）。邻接转轴改一个基列。与最大流：网络单纯形是特例。与高斯：每个基解一次线性方程。目标沿正检验数方向升。",-1)),a[6]||(a[6]=E("p",null,"一次转轴内部发生了什么？「选谁进基」和「选谁出基」是两个不同的决定：",-1)),(A(),r(s,null,{default:e(()=>[n(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E7%AE%97%E5%85%A8%E9%83%A8%E6%A3%80%E9%AA%8C%E6%95%B0%22%5D%20--%3E%20B%7B%22%E5%AD%98%E5%9C%A8%E6%AD%A3%E6%A3%80%E9%AA%8C%E6%95%B0%3F%22%7D%0A%20%20B%20--%20%E5%90%A6%20--%3E%20OPT%5B%22%E5%BD%93%E5%89%8D%E9%A1%B6%E7%82%B9%E6%9C%80%E4%BC%98%22%5D%0A%20%20B%20--%20%E6%98%AF%20--%3E%20C%5B%22%E6%8C%91%E6%AD%A3%E6%A3%80%E9%AA%8C%E6%95%B0%E5%88%97%E8%BF%9B%E5%9F%BA%3Cbr%3E%E7%9B%AE%E6%A0%87%E8%83%BD%E6%B2%BF%E8%AF%A5%E6%96%B9%E5%90%91%E5%8D%87%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%AF%94%E5%80%BC%E6%A3%80%E9%AA%8C%EF%BC%9Ab_i%20%2F%20a_ij%20%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A%20%20D%20--%3E%20E%7B%22%E8%AF%A5%E5%88%97%20a_ij%20%E5%85%A8%20%E2%89%A4%200%3F%22%7D%0A%20%20E%20--%20%E6%98%AF%20--%3E%20UNB%5B%22%E7%9B%AE%E6%A0%87%E6%97%A0%E7%95%8C%EF%BC%9A%E5%8F%AF%E4%BB%A5%E6%97%A0%E9%99%90%E8%B5%B0%22%5D%0A%20%20E%20--%20%E5%90%A6%20--%3E%20F%5B%22%E6%9C%80%E5%B0%8F%E6%AF%94%E5%80%BC%E8%A1%8C%E5%87%BA%E5%9F%BA%3Cbr%3E%E4%B8%80%E6%AC%A1%E9%AB%98%E6%96%AF%E6%B6%88%E5%85%83%E6%9B%B4%E6%96%B0%E8%A1%A8%22%5D%0A%20%20F%20--%3E%20A%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>这一步如果做错了，后面会循环打转：比值检验选错行，下一轮基可行解可能出负分量（违反 \\(x\\ge 0\\)），或者退化时原地转圈——Bland 规则「同时候选选下标最小」就是给这种情况上的保险。</p><p>与最大流：网络单纯形是特例。与高斯：每个基解一次线性方程。目标沿正检验数方向升。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写椭球法证明。不写商业求解器预处理。后课默认：LP 顶点最优；单纯形实用、最坏可指数。下一课 LP 对偶。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优在顶点；单纯形转轴改基。</li><li>最坏可指数；实践快。</li><li>分数解；整数要另法。</li><li>出处：Dantzig, 1963；CLRS 第 29 章。</li></ul>',6))])}const c=B(p,[["render",m]]);export{x as __pageData,c as default};
